-- Additional completion controls. Synthetic transaction only; no customer mail.
begin;
create temp table completion_threshold_ids(id uuid,expected text);
grant select,insert on completion_threshold_ids to authenticated;
create temp table completion_portal_ids(request_id uuid,share_id uuid,customer_id uuid);
grant select,insert on completion_portal_ids to authenticated,anon;
create temp table work_test_ids(owner_id uuid,editor_id uuid,session_id uuid,editor_session uuid,factor_id uuid,editor_factor uuid);
insert into work_test_ids values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select on work_test_ids to authenticated,anon;
insert into auth.users(id,email,email_confirmed_at) select owner_id,'owner-fixture@example.invalid',now() from work_test_ids union all select editor_id,'editor-fixture@example.invalid',now() from work_test_ids;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) select factor_id,owner_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'FIXTURE',now(),now() from work_test_ids union all select editor_factor,editor_id,'totp'::auth.factor_type,'verified'::auth.factor_status,'FIXTURE',now(),now() from work_test_ids;
insert into auth.sessions(id,user_id,factor_id,aal,created_at,updated_at) select session_id,owner_id,factor_id,'aal2'::auth.aal_level,now(),now() from work_test_ids union all select editor_session,editor_id,editor_factor,'aal2'::auth.aal_level,now(),now() from work_test_ids;
insert into public.work_members(email,user_id,role) select 'owner-fixture@example.invalid',owner_id,'owner' from work_test_ids union all select 'editor-fixture@example.invalid',editor_id,'editor' from work_test_ids;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
do $$declare denied boolean;begin
 perform public.work_set_roles('editor-fixture@example.invalid',array['editor','finance','designer'],true);
 if not exists(select 1 from public.work_members where email='editor-fixture@example.invalid' and role='finance' and roles @> array['editor','finance','designer']) then raise exception 'Multiple roles not persisted';end if;
 denied=false;begin perform public.work_set_roles('owner-fixture@example.invalid',array['finance'],true);exception when raise_exception then denied=true;end;if not denied then raise exception 'Owner changed own authority';end if;
 denied=false;begin perform public.work_set_roles('another@example.invalid',array['owner','editor'],true);exception when raise_exception then denied=true;end;if not denied then raise exception 'Ambiguous owner combination accepted';end if;
 perform public.work_set_grant_areas('editor-fixture@example.invalid',array['sales','procurement'],array['sales'],'all',true);
 denied=false;begin perform public.work_set_grant_areas('editor-fixture@example.invalid',array['sales','finance'],array['inventory'],'all',false);exception when raise_exception then denied=true;end;if not denied then raise exception 'Approval outside selected departments accepted';end if;
 if (select count(*) from public.work_grants where email='editor-fixture@example.invalid')<>2 then raise exception 'Invalid batch partially saved';end if;
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',editor_id,'aal','aal2','session_id',editor_session)::text,true) from work_test_ids;
set local role authenticated;
do $$declare denied boolean;begin
 if not public.work_has_access('content') or not public.work_has_access('finance') or not public.work_has_access('staff') or public.work_has_access('members') then raise exception 'Role union failed or escalated';end if;
 if not private.work_ops_allowed('sales',null,'approve') or private.work_ops_allowed('procurement',null,'approve') then raise exception 'Independent approval authority failed';end if;
 if not private.work_ops_allowed('procurement',null,'write') then raise exception 'Multiple departments not assigned';end if;
 denied=false;begin perform public.work_set_roles('editor-fixture@example.invalid',array['owner'],true);exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Member self-escalation accepted';end if;
 denied=false;begin perform public.work_set_grant_areas('editor-fixture@example.invalid',array['finance'],array['finance'],'all',true);exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Member self-approved';end if;
 denied=false;begin update public.work_members set roles=array['owner'] where user_id=auth.uid();exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'Direct membership edit allowed';end if;
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',editor_id,'aal','aal1','session_id',editor_session)::text,true) from work_test_ids;
set local role authenticated;
do $$begin if public.work_has_access('content') or public.work_has_access('finance') then raise exception 'Multi-role AAL1 bypass';end if;end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',owner_id,'aal','aal2','session_id',session_id)::text,true) from work_test_ids;
set local role authenticated;
select public.work_set_roles('editor-fixture@example.invalid',array['finance'],true);
select public.work_set_grant_areas('editor-fixture@example.invalid',array['sales'],array[]::text[],'all',true);
do $$begin
 if not exists(select 1 from public.work_members where email='editor-fixture@example.invalid' and roles=array['finance']) then raise exception 'Role removal failed';end if;
 if exists(select 1 from public.work_grants where email='editor-fixture@example.invalid' and area='sales' and approve_access) then raise exception 'Approval removal failed';end if;
 if not exists(select 1 from public.work_grants where email='editor-fixture@example.invalid' and area='procurement' and write_access) then raise exception 'Unselected department changed';end if;
 perform public.work_set_roles('editor-fixture@example.invalid',array['finance','editor'],true);
 perform public.work_set_member('editor-fixture@example.invalid','designer',true);
 if not exists(select 1 from public.work_members where email='editor-fixture@example.invalid' and roles=array['designer']) then raise exception 'Legacy single-role downgrade retained hidden roles';end if;
 if not exists(select 1 from jsonb_array_elements(public.work_backup_snapshot()->'members') m where m->>'email'='editor-fixture@example.invalid' and m->'roles'='["designer"]'::jsonb) then raise exception 'Roles missing from backup';end if;
end;$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',editor_id,'aal','aal2','session_id',editor_session)::text,true) from work_test_ids;
set local role authenticated;
do $$begin if public.work_has_access('content') or public.work_has_access('finance') or not public.work_has_access('staff') then raise exception 'Role removal not enforced against existing session';end if;end;$$;
reset role;
rollback;
select 'PASS: multiple roles and departments, separate approval, immediate revocation, protected owner, denied self-escalation/MFA bypass, legacy downgrade and backup coverage' as result;
